// A whole captured packet (u16 opcode | i8 slot | u16 length = the rest): its opcode renumbered in place.
inline void renumber_2976_packet(std::vector<uint8_t>& p) {
    if (p.size() < 5 || static_cast<size_t>(p[3] | p[4] << 8) != p.size() - 5) return;
    const uint16_t now = renumber_2976(static_cast<uint16_t>(p[0] | p[1] << 8));
    p[0] = static_cast<uint8_t>(now);
    p[1] = static_cast<uint8_t>(now >> 8);
}

